public sealed class FinanceE2ETests(PostgreSqlDatabaseFixture database)
{
    [Fact]public async Task PaymentReversalApprovalInvoiceHistoryAndIsolationFlow()
    {
        CancellationToken ct=TestContext.Current.CancellationToken;await database.ResetAsync(ct);Guid company=Guid.NewGuid(),other=Guid.NewGuid(),branch=Guid.NewGuid(),customer=Guid.NewGuid();string run=Guid.NewGuid().ToString("N")[..10];DateTimeOffset now=DateTimeOffset.UtcNow;Product product;ProductVariant variant;await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.AddRange(Company.Create(company,$"FIN_E2E_{run}","Finance E2E",now).Value,Company.Create(other,$"FIN_OTHER_{run}","Finance Other",now).Value);db.Branches.Add(Branch.Create(branch,company,"MAIN","Main",now).Value);db.Customers.Add(Customer.Create(customer,company,"FIN-C",CustomerType.Organization,null,null,null,"Finance Buyer",null,null,null,null,null,null,null,now).Value);product=Product.Create(Guid.NewGuid(),company,"FIN-P","Finance Shirt",null,"APPAREL","PCS",now).Value;variant=ProductVariant.Create(Guid.NewGuid(),product,"FIN-SKU","Blue",null,"L","BLUE",now).Value;db.Add(product);db.Add(variant);await db.SaveChangesAsync(ct);}
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId=company,username="finance-admin",displayName="Finance Administrator",password="StrongFinancePassword123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,ct)).EnsureSuccessStatusCode();Login login=await Json<Login>(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="finance-admin",password="StrongFinancePassword123"},ct),ct);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId=company}),ct);await WorkflowTestData.SeedPublishedOrderDefinitionAsync(database.ConnectionString, company, "finance-admin", ct);
        await Ok(client,Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=0,code="RAW",productVariantId=variant.Id,amount=100,currencyCode="IRR",validFrom="2026-01-01"}),ct);OrderView draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-09-01"}),ct),ct);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId=product.Id,productVariantId=variant.Id,quantity=2}),ct);draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company),ct),ct);OrderView submitted=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/submit",login.AccessToken,company,new{version=draft.Version}),ct),ct);Assert.NotNull(submitted.OrderNumber);
        PaymentView first=await Json<PaymentView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments",login.AccessToken,company,new{paymentMethodCode="cash",amount=50,currencyCode="IRR",referenceNumber="PAY-1",paidAtUtc=now}),ct),ct);FinanceBalanceView partial=await Get<FinanceBalanceView>($"/api/v1/orders/{draft.Id}/finance/balance");Assert.Equal(150,partial.Remaining);PaymentView duplicate=await Json<PaymentView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments",login.AccessToken,company,new{paymentMethodCode="cash",amount=50,currencyCode="IRR",referenceNumber="PAY-1",paidAtUtc=now}),ct),ct);Assert.Equal(first.Id,duplicate.Id);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments",login.AccessToken,company,new{paymentMethodCode="bank_transfer",amount=170,currencyCode="IRR",referenceNumber="PAY-2",paidAtUtc=now}),ct);FinanceBalanceView over=await Get<FinanceBalanceView>($"/api/v1/orders/{draft.Id}/finance/balance");Assert.Equal(20,over.Overpaid);PaymentView reversal=await Json<PaymentView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments/{first.Id}/reversals",login.AccessToken,company,new{amount=20,reason="correction",referenceNumber="REV-1"}),ct),ct);Assert.Equal(first.Id,reversal.OriginalPaymentId);FinanceBalanceView balanced=await Get<FinanceBalanceView>($"/api/v1/orders/{draft.Id}/finance/balance");Assert.Equal(200,balanced.NetPaid);using(HttpResponseMessage excessiveReverse=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments/{first.Id}/reversals",login.AccessToken,company,new{amount=40,reason="too much"}),ct))Assert.Equal(HttpStatusCode.BadRequest,excessiveReverse.StatusCode);
        using(HttpResponseMessage blockedInvoice=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Invoice",login.AccessToken,company),ct))Assert.Equal(HttpStatusCode.UnprocessableEntity,blockedInvoice.StatusCode);FinancialStateView approved=await Json<FinancialStateView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/decision",login.AccessToken,company,new{targetStatus=1,version=0}),ct),ct);Assert.Equal(FinancialStatus.Approved,approved.Status);Assert.NotNull(approved.ApprovedPriceSnapshotId);using(HttpResponseMessage stale=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/decision",login.AccessToken,company,new{targetStatus=3,reason="review",version=1}),ct))Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);InvoiceView proforma=await Json<InvoiceView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Proforma",login.AccessToken,company),ct),ct);InvoiceView invoice=await Json<InvoiceView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Invoice",login.AccessToken,company),ct),ct);Assert.StartsWith("PRO-2026-",proforma.InvoiceNumber,StringComparison.Ordinal);Assert.StartsWith("INV-2026-",invoice.InvoiceNumber,StringComparison.Ordinal);InvoiceView duplicateInvoice=await Json<InvoiceView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Invoice",login.AccessToken,company),ct),ct);Assert.Equal(invoice.Id,duplicateInvoice.Id);Assert.Equal(200,invoice.FinalTotal);Assert.Single(invoice.Items);
        FinancialStateView suspended=await Json<FinancialStateView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/decision",login.AccessToken,company,new{targetStatus=3,reason="manual review",version=approved.Version}),ct),ct);Assert.Equal(FinancialStatus.Suspended,suspended.Status);FinancialStateView rejected=await Json<FinancialStateView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/decision",login.AccessToken,company,new{targetStatus=2,reason="risk",version=suspended.Version}),ct),ct);Assert.Equal(FinancialStatus.Rejected,rejected.Status);FinanceHistoryView[] history=await Get<FinanceHistoryView[]>($"/api/v1/orders/{draft.Id}/finance/history");Assert.Contains(history,x=>x.EventType=="PaymentRegistered");Assert.Contains(history,x=>x.EventType=="PaymentReversed");Assert.Contains(history,x=>x.EventType=="InvoiceGenerated");using(HttpResponseMessage denied=await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/finance/balance",login.AccessToken,other),ct))Assert.Equal(HttpStatusCode.NotFound,denied.StatusCode);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/logout",login.AccessToken,null),ct);
        Login again=await Json<Login>(await client.PostAsJsonAsync("/api/v1/auth/login",new{username="finance-admin",password="StrongFinancePassword123"},ct),ct);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/me/company",again.AccessToken,null,new{companyId=company}),ct);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments/{first.Id}/reversals",again.AccessToken,company,new{amount=30,reason="final correction",referenceNumber="REV-2"}),ct);using(HttpResponseMessage fullyReversed=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments/{first.Id}/reversals",again.AccessToken,company,new{amount=1,reason="repeat"}),ct))Assert.Equal(HttpStatusCode.Conflict,fullyReversed.StatusCode);await using(CoreDbContext configuration=database.CreateAdministrationCoreDbContext()){await configuration.Database.ExecuteSqlRawAsync("UPDATE barang.lookup_values SET is_active=FALSE WHERE code='cash' AND lookup_type_id='13000000-0000-0000-0000-000000000001'",ct);}using(HttpResponseMessage inactiveMethod=await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/payments",again.AccessToken,company,new{paymentMethodCode="cash",amount=1,currencyCode="IRR",referenceNumber="PAY-INACTIVE",paidAtUtc=now}),ct))Assert.Equal(HttpStatusCode.UnprocessableEntity,inactiveMethod.StatusCode);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/logout",again.AccessToken,null),ct);
        await using(CoreDbContext verify=database.CreateAdministrationCoreDbContext()){Assert.True(await verify.AuditEvents.IgnoreQueryFilters().AnyAsync(x=>x.Action=="payment.registered",ct));Assert.True(await verify.AuditEvents.IgnoreQueryFilters().AnyAsync(x=>x.Action=="payment.reversed",ct));Assert.True(await verify.AuditEvents.IgnoreQueryFilters().AnyAsync(x=>x.Action=="invoice.generated",ct));}
        async Task<T> Get<T>(string uri)=>await Json<T>(await client.SendAsync(Req(HttpMethod.Get,uri,login.AccessToken,company),ct),ct);
    }
    [Fact]public async Task ExplicitInvoiceIssuanceDoesNotAutoIssueAndRemainsUnpaidUntilPayment()
    {
        CancellationToken ct=TestContext.Current.CancellationToken;await database.ResetAsync(ct);Guid company=Guid.NewGuid(),branch=Guid.NewGuid(),customer=Guid.NewGuid(),productId=Guid.NewGuid(),variantId=Guid.NewGuid();string run=Guid.NewGuid().ToString("N")[..10];DateTimeOffset now=DateTimeOffset.UtcNow;
        await using(CoreDbContext db=database.CreateAdministrationCoreDbContext()){db.Companies.Add(Company.Create(company,$"FIN_EXPLICIT_{run}","Explicit Finance",now).Value);db.Branches.Add(Branch.Create(branch,company,"MAIN","Main",now).Value);db.Customers.Add(Customer.Create(customer,company,$"FIN-C-{run}",CustomerType.Organization,null,null,null,"Finance Buyer",null,null,null,null,null,null,null,now).Value);Product product=Product.Create(productId,company,$"FIN-P-{run}","Finance Shirt",null,"APPAREL","PCS",now).Value;ProductVariant variant=ProductVariant.Create(variantId,product,$"FIN-SKU-{run}","Blue",null,"L","BLUE",now).Value;db.Add(product);db.Add(variant);await db.SaveChangesAsync(ct);}
        await using PostgreSqlCoreApiFactory factory=new(database.ConnectionString);using HttpClient client=factory.CreateClient();using HttpRequestMessage bootstrap=new(HttpMethod.Post,"/api/v1/security/bootstrap"){Content=JsonContent.Create(new{companyId=company,username=$"finance-explicit-{run}",displayName="Explicit Finance",password="StrongFinancePassword123"})};bootstrap.Headers.Add("X-Bootstrap-Secret","test-bootstrap-secret-123456789");(await client.SendAsync(bootstrap,ct)).EnsureSuccessStatusCode();Login login=await Json<Login>(await client.PostAsJsonAsync("/api/v1/auth/login",new{username=$"finance-explicit-{run}",password="StrongFinancePassword123"},ct),ct);await Ok(client,Req(HttpMethod.Post,"/api/v1/auth/me/company",login.AccessToken,null,new{companyId=company}),ct);await WorkflowTestData.SeedPublishedOrderDefinitionAsync(database.ConnectionString,company,$"finance-explicit-{run}",ct);
        await Ok(client,Req(HttpMethod.Post,"/api/v1/pricing/tariffs",login.AccessToken,company,new{tariffType=0,code=$"RAW-{run}",productVariantId=variantId,amount=100,currencyCode="IRR",validFrom="2026-01-01"}),ct);OrderView draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Post,"/api/v1/orders",login.AccessToken,company,new{branchId=branch,customerId=customer,source="Internal",orderDate="2026-09-01"}),ct),ct);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/items",login.AccessToken,company,new{productId,productVariantId=variantId,quantity=2}),ct);draft=await Json<OrderView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}",login.AccessToken,company),ct),ct);await Ok(client,Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/submit",login.AccessToken,company,new{version=draft.Version}),ct);
        InvoiceView[] beforeApproval=await Json<InvoiceView[]>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/finance/invoices",login.AccessToken,company),ct),ct);Assert.DoesNotContain(beforeApproval,x=>x.InvoiceType==InvoiceType.Invoice);FinancialStateView approved=await Json<FinancialStateView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/decision",login.AccessToken,company,new{targetStatus=1,version=0}),ct),ct);Assert.Equal(FinancialStatus.Approved,approved.Status);InvoiceView[] afterApproval=await Json<InvoiceView[]>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/finance/invoices",login.AccessToken,company),ct),ct);Assert.DoesNotContain(afterApproval,x=>x.InvoiceType==InvoiceType.Invoice);InvoiceView invoice=await Json<InvoiceView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Invoice",login.AccessToken,company),ct),ct);Assert.Equal(InvoiceStatus.Issued,invoice.Status);InvoiceView retry=await Json<InvoiceView>(await client.SendAsync(Req(HttpMethod.Post,$"/api/v1/orders/{draft.Id}/finance/invoices/Invoice",login.AccessToken,company),ct),ct);Assert.Equal(invoice.Id,retry.Id);FinanceBalanceView balance=await Json<FinanceBalanceView>(await client.SendAsync(Req(HttpMethod.Get,$"/api/v1/orders/{draft.Id}/finance/balance",login.AccessToken,company),ct),ct);Assert.Equal(0,balance.NetPaid);Assert.Equal(invoice.FinalTotal,balance.Remaining);await using(CoreDbContext notificationEvidence=database.CreateAdministrationCoreDbContext()){using IDisposable scope=database.CompanyContext.BeginScope(company);Assert.True(await notificationEvidence.OutboxMessages.IgnoreQueryFilters().AnyAsync(x=>x.EventType=="notification.requested"&&x.CompanyId==company&&x.CorrelationId!.StartsWith("finance.approved:"+draft.Id.ToString("N")),ct));Assert.True(await notificationEvidence.OutboxMessages.IgnoreQueryFilters().AnyAsync(x=>x.EventType=="notification.requested"&&x.CompanyId==company&&x.CorrelationId!.StartsWith("finance.invoice.issued:"+invoice.Id.ToString("N")),ct));}
    }
    private static HttpRequestMessage Req(HttpMethod method,string uri,string token,Guid? company,object? body=null){HttpRequestMessage r=new(method,uri);r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);if(company is not null)r.Headers.Add("X-Company-ID",company.ToString());if(body is not null)r.Content=JsonContent.Create(body);return r;}private static async Task Ok(HttpClient client,HttpRequestMessage request,CancellationToken ct){using HttpResponseMessage response=await client.SendAsync(request,ct);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {await response.Content.ReadAsStringAsync(ct)}");}private static async Task<T> Json<T>(HttpResponseMessage response,CancellationToken ct){using(response){string payload=await response.Content.ReadAsStringAsync(ct);Assert.True(response.IsSuccessStatusCode,$"{response.StatusCode}: {payload}");return(await response.Content.ReadFromJsonAsync<T>(TestJson.ApiOptions,ct))!;}}private sealed record Login(string AccessToken);
}
